WITH parsed AS (SELECT id, customer_id, items, ship_to, COALESCE(attributes['device'], 'direct') AS device_or_default, ship_to.city AS ship_city FROM carts) SELECT ship_city, COUNT(*) AS num_rows, SORT_ARRAY(COLLECT_SET(ship_city)) AS ship_city_list, SORT_ARRAY(COLLECT_SET(ship_city)) AS ship_city_list_2, COUNT(CASE WHEN ship_city = 'Berlin' THEN 1 END) AS berlin_count, SORT_ARRAY(COLLECT_SET(ship_city)) AS ship_city_list_3, COUNT(*) FILTER (WHERE ship_city = 'Berlin') AS berlin_rows FROM parsed GROUP BY 1;
